function dummy_v52_table_exists(string $table): bool {
    static $cache=[];
    if(!preg_match('/^[A-Za-z][A-Za-z0-9_]{0,63}$/',$table)) return false;
    if(array_key_exists($table,$cache)) return $cache[$table];
    try{$q=db()->prepare('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? LIMIT 1');$q->execute([$table]);return $cache[$table]=(bool)$q->fetchColumn();}
    catch(Throwable $e){return $cache[$table]=false;}
}
function dummy_v52_columns(string $table): array {
    static $cache=[]; if(isset($cache[$table])) return $cache[$table]; if(!dummy_v52_table_exists($table)) return $cache[$table]=[];
    try{$q=db()->prepare('SELECT COLUMN_NAME,IS_NULLABLE,COLUMN_DEFAULT,EXTRA,COLUMN_TYPE,DATA_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? ORDER BY ORDINAL_POSITION');$q->execute([$table]);$o=[];foreach($q->fetchAll() as $r)$o[(string)$r['COLUMN_NAME']]=$r;return $cache[$table]=$o;}
    catch(Throwable $e){return $cache[$table]=[];}
}
function dummy_v52_enum_values(array $column): array {
    $type=(string)($column['COLUMN_TYPE']??''); if(!str_starts_with(strtolower($type),'enum(')) return [];
    preg_match_all("/'((?:[^'\\\\]|\\\\.)*)'/",$type,$m); return array_map(static fn($v)=>stripcslashes((string)$v),$m[1]??[]);
}
function dummy_v52_normalize_for_column(array $column,$value){
    if($value===null) return null; $enum=dummy_v52_enum_values($column);
    if($enum && !in_array((string)$value,$enum,true)){
        foreach(['active','approved','published','completed','verified','pending','draft','open','enabled'] as $f)if(in_array($f,$enum,true))return $f;
        return $enum[0]??$value;
    }
    $t=strtolower((string)($column['DATA_TYPE']??''));
    if(in_array($t,['tinyint','smallint','mediumint','int','bigint'],true))return (int)$value;
    if(in_array($t,['decimal','float','double'],true))return (float)$value;
    if($t==='json' && is_array($value))return json_encode($value,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
    return is_array($value)?json_encode($value,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):$value;
}
