function dummy_v52_allowed_tables(): array { return dummy_v910_safe_tables(); }
function dummy_v52_scope(?int $tenantId=null): array {
    $tenant=null;$cityId=0;$cityName='Shahkot';
    try{
      if($tenantId && dummy_v52_table_exists('tenants')){$q=db()->prepare('SELECT t.*,c.name city_name,c.slug city_slug FROM tenants t JOIN cities c ON c.id=t.city_id WHERE t.id=? LIMIT 1');$q->execute([$tenantId]);$tenant=$q->fetch()?:null;}
      if(!$tenant && function_exists('current_tenant'))$tenant=current_tenant();
      if($tenant){$tenantId=(int)$tenant['id'];$cityId=(int)$tenant['city_id'];$cityName=(string)($tenant['city_name']??$cityName);}
      if($cityId<1){$q=db()->query("SELECT id,name FROM cities WHERE status=1 ORDER BY (LOWER(slug)='shahkot') DESC,id ASC LIMIT 1");$c=$q->fetch();if($c){$cityId=(int)$c['id'];$cityName=(string)$c['name'];}}
    }catch(Throwable $e){}
    return ['tenant_id'=>(int)($tenantId??0),'city_id'=>$cityId,'city_name'=>$cityName,'tenant'=>$tenant];
}
function dummy_v52_owner_id(?int $preferred=null): int {
    if($preferred&&$preferred>0)return $preferred;
    try{if(function_exists('current_user')){$u=current_user();if($u&&!empty($u['id']))return (int)$u['id'];}$q=db()->query("SELECT id FROM users WHERE status='active' ORDER BY (role='admin') DESC,id ASC LIMIT 1");return (int)($q->fetchColumn()?:0);}catch(Throwable $e){return 0;}
}
function dummy_v52_register(int $batchId,int $seq,string $table,int $recordId,string $label=''): bool {
    if($batchId<1||$recordId<1||!in_array($table,dummy_v910_safe_tables(),true))return false;
    try{$q=db()->prepare('INSERT IGNORE INTO dummy_data_registry(batch_id,sequence_no,table_name,record_id,record_label) VALUES(?,?,?,?,?)');$q->execute([$batchId,$seq,$table,$recordId,mb_substr($label,0,190)]);return $q->rowCount()>0||true;}catch(Throwable $e){return false;}
}
function dummy_v910_required_default(string $name,array $col,array $ctx){
    $n=strtolower($name);$t=strtolower((string)($col['DATA_TYPE']??''));$enum=dummy_v52_enum_values($col);
    if($enum){foreach(['active','approved','published','completed','pending','open','android','web','normal','manual','fixed','trial'] as $x)if(in_array($x,$enum,true))return $x;return $enum[0]??'';}
    if($n==='tenant_id')return (int)$ctx['tenant_id']; if($n==='city_id')return (int)$ctx['city_id'];
    if(preg_match('/(^|_)user_id$/',$n)||in_array($n,['owner_id','created_by','updated_by','assigned_by','seller_user_id','buyer_user_id','patient_user_id','developer_user_id','owner_user_id','agent_user_id'],true))return (int)$ctx['owner_id'];
    if(str_contains($n,'email'))return 'demo-'.$ctx['tag'].'@example.invalid';
    if(str_contains($n,'phone')||str_contains($n,'whatsapp'))return '0300-555-0199';
    if(str_contains($n,'slug')||str_contains($n,'key')||str_contains($n,'code')||str_contains($n,'number'))return 'demo-'.$ctx['tag'].'-'.substr(sha1($name.microtime(true)),0,8);
    if(str_contains($n,'status'))return 'active';
    if($t==='date')return date('Y-m-d'); if(in_array($t,['datetime','timestamp'],true))return date('Y-m-d H:i:s');
    if(in_array($t,['tinyint','smallint','mediumint','int','bigint'],true))return 0;
    if(in_array($t,['decimal','float','double'],true))return 0;
    if($t==='json')return '{}'; if(in_array($t,['text','mediumtext','longtext'],true))return 'ShahkotPK v9.1 demonstration record.';
    return 'Demo '.$ctx['tag'];
}
function dummy_v910_insert(string $table,array $data,int $batchId,int &$seq,string $label,array &$summary,array $ctx): int {
    if(!in_array($table,dummy_v910_safe_tables(),true)||!dummy_v52_table_exists($table)){ $summary['skipped'][$table]='table unavailable'; return 0; }
    $cols=dummy_v52_columns($table);$filtered=[];
    foreach($data as $k=>$v)if(isset($cols[$k]))$filtered[$k]=dummy_v52_normalize_for_column($cols[$k],$v);
    foreach($cols as $name=>$col){
      $extra=strtolower((string)($col['EXTRA']??'')); if(str_contains($extra,'auto_increment')||str_contains($extra,'generated'))continue;
      if(array_key_exists($name,$filtered))continue;
      $nullable=strtoupper((string)($col['IS_NULLABLE']??'YES'))==='YES';$default=$col['COLUMN_DEFAULT']??null;
      if(!$nullable && $default===null)$filtered[$name]=dummy_v52_normalize_for_column($col,dummy_v910_required_default($name,$col,$ctx));
    }
    if(!$filtered){$summary['warnings'][]="$table: no compatible columns";return 0;}
    try{$names=array_keys($filtered);$sql='INSERT INTO `'.$table.'` (`'.implode('`,`',$names).'`) VALUES ('.implode(',',array_fill(0,count($names),'?')).')';$q=db()->prepare($sql);$q->execute(array_values($filtered));$id=(int)db()->lastInsertId();if($id>0){$seq++;if(!dummy_v52_register($batchId,$seq,$table,$id,$label)){try{db()->prepare("DELETE FROM `$table` WHERE id=? LIMIT 1")->execute([$id]);}catch(Throwable $x){}$summary['warnings'][]="$table: registry failed";return 0;}$summary['inserted'][$table]=($summary['inserted'][$table]??0)+1;}return $id;}
    catch(Throwable $e){$summary['warnings'][]=mb_substr($table.': '.$e->getMessage(),0,350);return 0;}
}
function dummy_v910_insert_setting_table(string $table,array $data,array &$summary,array $ctx): void {
    if(!dummy_v52_table_exists($table))return; $cols=dummy_v52_columns($table);$f=[];foreach($data as $k=>$v)if(isset($cols[$k]))$f[$k]=dummy_v52_normalize_for_column($cols[$k],$v);if(!$f)return;
    try{$keys=array_keys($f);$upd=[];foreach($keys as $k)if($k!=='tenant_id')$upd[]="`$k`=VALUES(`$k`)";$sql='INSERT INTO `'.$table.'` (`'.implode('`,`',$keys).'`) VALUES ('.implode(',',array_fill(0,count($keys),'?')).')'.($upd?' ON DUPLICATE KEY UPDATE '.implode(',',$upd):'');db()->prepare($sql)->execute(array_values($f));$summary['configured'][$table]=1;}catch(Throwable $e){$summary['warnings'][]=mb_substr($table.': '.$e->getMessage(),0,350);}
}
