function dummy_v543_delete_all_managed(): array {
    if(!dummy_v52_table_exists('dummy_data_batches'))return ['batches'=>0,'deleted'=>0,'warnings'=>[]];$out=['batches'=>0,'deleted'=>0,'warnings'=>[]];
    try{$q=db()->query("SELECT id FROM dummy_data_batches WHERE status IN ('active','loading','failed','partial_deleted') ORDER BY id DESC");foreach($q->fetchAll(PDO::FETCH_COLUMN) as $id){$r=dummy_v52_delete_batch((int)$id,null);$out['batches']++;$out['deleted']+=(int)($r['deleted']??0);$out['warnings']=array_merge($out['warnings'],$r['warnings']??[]);}}catch(Throwable $e){$out['warnings'][]=mb_substr($e->getMessage(),0,280);}return $out;
}
function dummy_v52_delete_batch(int $batchId,?int $tenantId=null): array {
    if($batchId<1||!dummy_v52_table_exists('dummy_data_batches'))throw new InvalidArgumentException('Invalid demo batch.');$q=db()->prepare('SELECT * FROM dummy_data_batches WHERE id=? LIMIT 1');$q->execute([$batchId]);$batch=$q->fetch();if(!$batch)throw new RuntimeException('Demo batch not found.');
    if($tenantId!==null){$s=dummy_v52_scope($tenantId);$tid=(int)$s['tenant_id'];$city=(int)$s['city_id'];$belongs=$tid>0?(int)($batch['tenant_id']??0)===$tid:(int)($batch['city_id']??0)===$city;if(!$belongs)throw new RuntimeException('Batch is outside the active tenant scope.');}
    if(($batch['status']??'')==='deleted')return ['batch_id'=>$batchId,'deleted'=>0,'already_deleted'=>true,'warnings'=>[]];$allowed=array_flip(dummy_v910_safe_tables());$deleted=0;$warnings=[];$q=db()->prepare('SELECT * FROM dummy_data_registry WHERE batch_id=? ORDER BY sequence_no DESC,id DESC');$q->execute([$batchId]);
    foreach($q->fetchAll() as $r){$table=(string)$r['table_name'];$id=(int)$r['record_id'];if(!isset($allowed[$table])||$id<1||!dummy_v52_table_exists($table))continue;try{$st=db()->prepare("DELETE FROM `$table` WHERE id=? LIMIT 1");$st->execute([$id]);$deleted+=$st->rowCount();}catch(Throwable $e){$warnings[]=mb_substr($table.' #'.$id.': '.$e->getMessage(),0,260);}}
    $status=$warnings?'partial_deleted':'deleted';db()->prepare('UPDATE dummy_data_batches SET status=?,deleted_at=NOW(),meta_json=? WHERE id=?')->execute([$status,dummy_v910_json(['deleted_records'=>$deleted,'warnings'=>$warnings]),$batchId]);if(function_exists('tenant_audit'))tenant_audit('dummy_data.deleted','dummy_data_batch',$batchId,'Deleted registry-managed demo data',['deleted'=>$deleted,'warnings'=>count($warnings)]);return ['batch_id'=>$batchId,'deleted'=>$deleted,'status'=>$status,'warnings'=>$warnings];
}
function dummy_v52_delete_for_tenant(?int $tenantId=null): array {$s=dummy_v52_scope($tenantId);$tid=(int)$s['tenant_id'];$cid=(int)$s['city_id'];$where=[];$p=[];if($tid>0){$where[]='tenant_id=?';$p[]=$tid;}else{$where[]='city_id=?';$p[]=$cid;}$where[]="status IN ('active','loading','failed','partial_deleted')";$q=db()->prepare('SELECT id FROM dummy_data_batches WHERE '.implode(' AND ',$where).' ORDER BY id DESC');$q->execute($p);$o=['batches'=>0,'deleted'=>0,'warnings'=>[]];foreach($q->fetchAll(PDO::FETCH_COLUMN) as $id){$r=dummy_v52_delete_batch((int)$id,$tid>0?$tid:null);$o['batches']++;$o['deleted']+=(int)$r['deleted'];$o['warnings']=array_merge($o['warnings'],$r['warnings']??[]);}return $o;}
function dummy_v52_batches(?int $tenantId=null,int $limit=20): array {if(!dummy_v52_table_exists('dummy_data_batches'))return [];$s=dummy_v52_scope($tenantId);$tid=(int)$s['tenant_id'];$cid=(int)$s['city_id'];$w=[];$p=[];if($tid>0){$w[]='b.tenant_id=?';$p[]=$tid;}elseif($cid>0){$w[]='b.city_id=?';$p[]=$cid;}try{$sql='SELECT b.*,c.name city_name,u.name creator_name FROM dummy_data_batches b LEFT JOIN cities c ON c.id=b.city_id LEFT JOIN users u ON u.id=b.created_by'.($w?' WHERE '.implode(' AND ',$w):'').' ORDER BY b.id DESC LIMIT '.max(1,min(100,$limit));$q=db()->prepare($sql);$q->execute($p);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function dummy_v52_tenants(): array {if(!dummy_v52_table_exists('tenants'))return [];try{return db()->query("SELECT t.id,t.site_name,t.status,c.name city_name FROM tenants t JOIN cities c ON c.id=t.city_id WHERE t.status='active' ORDER BY t.is_master DESC,c.name")->fetchAll()?:[];}catch(Throwable $e){return [];}}
function dummy_v52_status(?int $tenantId=null): array {$s=dummy_v52_scope($tenantId);$b=dummy_v52_batches($tenantId,100);$active=0;$records=0;foreach($b as $x)if(in_array((string)$x['status'],['active','loading','partial_deleted'],true)){$active++;$records+=(int)$x['record_count'];}return ['scope'=>$s,'active_batches'=>$active,'records'=>$records,'batches'=>$b];}
