    try{
      if((string)setting('dummy_data_v543_replace_pending','0')==='1'||(string)setting('dummy_data_v910_replace_pending','0')==='1'||(string)setting('dummy_data_v920_replace_pending','0')==='1'||(string)setting('dummy_data_v930_replace_pending','0')==='1'){
